SELECT qryElektrolyseureInAllenTeilanlagen.Teilanlagenbezeichnung, qryUnAlleElektrolyseure.Datum, Avg(qryUnAlleElektrolyseure.[I Gesamt]) AS [Mittelwert von I Gesamt], Avg(qryUnAlleElektrolyseure.i) AS [Mittelwert von i], Avg(qryUnAlleElektrolyseure.Cc) AS [Mittelwert von Cc], Avg(qryUnAlleElektrolyseure.[t Ka]) AS [Mittelwert von t Ka], Avg(qryUnAlleElektrolyseure.[t An]) AS [Mittelwert von t An], Avg(qryUnAlleElektrolyseure.Un) AS [Mittelwert von Un], qryUnAlleElektrolyseure.iRef, Count(qryUnAlleElektrolyseure.Elektrolyseur) AS [Anzahl von Elektrolyseur]
FROM qryElektrolyseureInAllenTeilanlagen INNER JOIN qryUnAlleElektrolyseure ON qryElektrolyseureInAllenTeilanlagen.Elektrolyseurbezeichnung = qryUnAlleElektrolyseure.Elektrolyseur
GROUP BY qryElektrolyseureInAllenTeilanlagen.Teilanlagenbezeichnung, qryUnAlleElektrolyseure.Datum, qryUnAlleElektrolyseure.iRef;
